function resumer<T extends { etat: string }>(liste: T[]): Record<string, number> {
  const r: Record<string, number> = {};
  for (const c of liste) r[c.etat] = (r[c.etat] ?? 0) + 1;
  return r;
}

function estCreee(x: unknown): x is Commande {
  return typeof x === "object" && x !== null
    && (x as Commande).etat === "créée"
    && typeof (x as Commande).id === "number"
    && typeof (x as Commande).total === "number";
}

function traiter(texte: string, ev: Evenement): Record<string, number> {
  let donnees: unknown;
  try {
    donnees = JSON.parse(texte);
  } catch {
    throw new Error("JSON invalide");
  }
  const commandes = Array.isArray(donnees) ? donnees.filter(estCreee) : [];
  const suivantes = commandes.map(c => {
    try {
      return avancer(c, ev);
    } catch {
      return c;
    }
  });
  return resumer(suivantes);
}
